  min-width: 0;
}
.flight--empty {
  visibility: hidden;
}
.flight-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0 6px;
  min-width: 0;
}
.flight-plane {
  flex: 0 0 auto;
  color: var(--violet);
}
/* Taking off on the way out, coming home the other way. The picture points
   along the reader's line, so a right-to-left page turns it round too. */
.flight--out .flight-plane {
  transform: rotate(45deg);
}
.flight--back .flight-plane {
  transform: rotate(135deg);
}
[dir="rtl"] .flight--out .flight-plane {
  transform: rotate(-45deg);
}
[dir="rtl"] .flight--back .flight-plane {
  transform: rotate(-135deg);
}
.flight-title {
  font-weight: 800;
}
.flight-day {
  color: var(--muted);
  font-size: 0.78rem;
  white-space: nowrap;
}
.flight-note {
  margin: 0;
  color: var(--muted);
  font-size: 0.82rem;
}
.flight-route {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
  letter-spacing: 0.04em;
}
.flight-from {
  width: 4.2em;
  font: inherit;
  text-transform: uppercase;
  text-align: center;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--paper);
  color: var(--ink);
}
.flight-from[aria-invalid="true"] {
  border-color: #c0392b;
}
.flight-arrow {
  color: var(--muted);
}
[dir="rtl"] .flight-arrow {
  transform: scaleX(-1);
}
.flight-fare,
.flight-search {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 6px;
  color: var(--ink);
  text-decoration: none;
}
.flight-search {
  color: var(--violet-dark);
  font-weight: 700;
  text-decoration: underline;
}
.flight-time,
.flight-price {
  font-weight: 800;
}
.flight-price {
  color: var(--violet-dark);
}
.flight-dot {
  color: var(--muted);
}
.flight-partner {
