.flight-time,
.flight-price {
  font-weight: 800;
}
.flight-price {
  color: var(--violet-dark);
}
.flight-dot {
  color: var(--muted);
}
.flight-partner {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--muted);
}
.flight-partner::after {
  content: " ↗";
}
.flight-change {
  align-self: flex-start;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: 0.78rem;
  color: var(--violet-dark);
  text-decoration: underline;
  cursor: pointer;
