cd /home/claude/EdFringeNow; python3 - <<'EOF'
p='site/planNG/lib/holidays.js'; s=open(p).read()
s=s.replace('''/** The file for a country's holidays. */''','''const DAY_NAMES = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
const nextDay = (iso, by) => {
  const d = new Date(`${iso}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + by);
  return d.toISOString().slice(0, 10);
};

/**
 * The breaks the holidays make: each run of days off around a holiday, the
 * country's weekend included, carried over any single work day that has days
 * off on both sides. Only breaks that reach into the span are kept.
 * @param {{weekend?: string[], holidays: {date: string, name: object}[]}} doc
 * @param {{from: string, to: string}} span
 * @param {string} locale the page's language
 * @returns {{from: string, to: string, days: number, workdays: number, weekend: boolean, names: string[]}[]}
 */
export function holidayBreaks(doc, span, locale) {
  const weekend = new Set(doc.weekend || ["sat", "sun"]);
  const named = new Map();
  for (const h of doc.holidays) {
    const name = h.name[locale] || h.name.en || Object.values(h.name)[0];
    named.set(h.date, [...(named.get(h.date) || []), name]);
  }
  const isWeekend = (iso) => weekend.has(DAY_NAMES[new Date(`${iso}T12:00:00Z`).getUTCDay()]);
  const off = (iso) => named.has(iso) || isWeekend(iso);
  // One step outwards: the next day off, or the day beyond a lone work day.
  const reach = (iso, dir) => {
    if (off(nextDay(iso, dir))) return { to: nextDay(iso, dir), bridged: 0 };
    if (off(nextDay(iso, 2 * dir))) return { to: nextDay(iso, 2 * dir), bridged: 1 };
    return null;
  };
  const breaks = [];
  let covered = "";
  for (const date of [...named.keys()].sort()) {
    if (date <= covered) continue;
    let from = date;
    let to = date;
    let workdays = 0;
    for (let step; (step = reach(from, -1)); from = step.to) workdays += step.bridged;
    for (let step; (step = reach(to, 1)); to = step.to) workdays += step.bridged;
    covered = to;
    if (to < span.from || from > span.to) continue;
    const days = [];
    for (let d = from; d <= to; d = nextDay(d, 1)) days.push(d);
    breaks.push({
      from,
      to,
      days: days.length,
      workdays,
      weekend: days.some(isWeekend),
      names: [...new Set(days.flatMap((d) => named.get(d) || []))],
    });
  }
  return breaks;
}

/** The file for a country's holidays. */''')
open(p,'w').write(s)
EOF
cat >> site/planNG/lib/__tests__/holidays.test.mjs <<'EOF'

test("a break runs over the weekend and a lone work day between days off", async () => {
  const { holidayBreaks } = await import("../holidays.js");
  const span = { from: "2026-01-01", to: "2026-12-31" };
  const doc = (dates, weekend) => ({ weekend, holidays: dates.map((date) => ({ date, name: { en: `H${date.slice(8)}` } })) });
  // Wed 7 + Thu 8 Oct, Fri 9 a work day, Sat 10 + Sun 11 the weekend.
  assert.deepEqual(holidayBreaks(doc(["2026-10-07", "2026-10-08"]), span, "en"), [
    { from: "2026-10-07", to: "2026-10-11", days: 5, workdays: 1, weekend: true, names: ["H07", "H08"] },
  ]);
  // A Tuesday alone: Sat-Sun, Mon bridged, Tue.
  assert.equal(holidayBreaks(doc(["2026-10-13"]), span, "en")[0].from, "2026-10-10");
  // A Wednesday alone stands alone: two work days either side.
  assert.deepEqual(holidayBreaks(doc(["2026-10-14"]), span, "en")[0], { from: "2026-10-14", to: "2026-10-14", days: 1, workdays: 0, weekend: false, names: ["H14"] });
  // The country's own weekend: a Thursday runs into Friday-Saturday.
  assert.equal(holidayBreaks(doc(["2026-10-15"], ["fri", "sat"]), span, "en")[0].to, "2026-10-17");
  // A break outside the span is dropped.
  assert.deepEqual(holidayBreaks(doc(["2027-10-14"]), span, "en"), []);
});
EOF
