    const el = e.target.closest("[data-card]");
    if (el) show(el);
  });
  host.addEventListener("pointerout", (e) => {
    const el = e.target.closest("[data-card]");
    if (el && !el.contains(e.relatedTarget)) hide();
  });
  host.addEventListener("focusin", (e) => {
    const el = e.target.closest("[data-card]");
    if (el) show(el);
  });
  host.addEventListener("focusout", hide);
}''')
