import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const [,, url, out, width, sel, setup, fares, hover] = process.argv;
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: Number(width), height: 900 }, deviceScaleFactor: 1 });
const errs = [];
p.on('pageerror', e => errs.push('pageerror ' + e.message));
await p.route('https://unpkg.com/**', r => r.abort());
if (fares) await p.route('**/api/fares**', r => r.fulfill({ status: 200, contentType: 'application/json', body: fares }));
if (setup) await p.addInitScript(setup);
await p.goto(url, { waitUntil: 'networkidle' });
await p.waitForTimeout(1500);
if (hover) { await p.hover(hover); await p.waitForTimeout(300); }
await p.locator(sel || 'body').first().screenshot({ path: out });
console.log(p.url());
console.log(errs.join('\n'));
await b.close();

